#!/usr/bin/env bash
# Phase 4: re-runs every Node suite with VERBOSE=1 so that EVERY individual assertion (PASS/FAIL line) is retained, per suite and time zone. Usage: bash run-verbose.sh <outdir>
cd "$(dirname "$0")" || exit 9; OUT=${1:-logs/p4-verbose}; C3T=$(mktemp -d); git -C .. archive c4-base | tar -x -C $C3T; export C3_TREE=$C3T; P1T=$(mktemp -d); git -C .. archive v0.6-candidate-4-phase1-final | tar -x -C $P1T; export P1_TREE=$P1T
for tz in UTC Europe/London; do d=$OUT/${tz//\//_}; mkdir -p $d; for t in test7 test8 test9 domtest domtest2 test-failed-import test-export-nohistory test-timezones test-po-edge test-structure test-paging test-fillcap test-export-repeat test-cache test-phase1 test-blank-qty test-uom test-missing-values test-fglt-note test-forecast-conf test-supplier-eligibility test-na-constraints; do TZ=$tz VERBOSE=1 node $t.js > $d/$t.log 2>&1; echo "$tz $t exit $? PASS-lines $(grep -c '^PASS' $d/$t.log) FAIL-lines $(grep -c '^FAIL' $d/$t.log)"; done; done
